// Puzzles (data/chess/puzzles.json): own positions generated by tests/games/chess/generate-puzzles.ts
// and checked there and in the tests — a single solving move each.

import { Chess } from 'chess.js';
import { MATE, materialBalance, scoreMoves } from '../ai.ts';
import { explainMove } from './hints.ts';

export type PuzzleKind = 'mate1' | 'material' | 'fork';

export interface Puzzle {
  id: string;
  kind: PuzzleKind;
  fen: string;
  /** First move is the answer; the rest is the expected continuation (shown after solving). */
  solution: string[];
  hint: string;
  /** 1 easy … 3 harder (by number of pieces on the board). */
  difficulty: 1 | 2 | 3;
}

export interface PuzzleFile {
  version: 1;
  puzzles: Puzzle[];
}

export const PUZZLE_KIND_LABEL: Record<PuzzleKind, { title: string; task: string }> = {
  mate1: { title: 'Mat jedním tahem', task: 'Dej mat jedním tahem!' },
  material: { title: 'Získej figuru', task: 'Najdi tah, kterým získáš figuru.' },
  fork: { title: 'Vidlička', task: 'Napadni dvě figury najednou!' },
};

/** Search depth used to prove material puzzles (the same in the generator and the tests). */
export const PUZZLE_DEPTH = 4;
/** The solving move must win at least this much (centipawns) over the current material balance. */
export const WIN_MARGIN = 250;
/** …and every other move must be at least this much worse. */
export const UNIQUE_MARGIN = 200;

/** All moves that mate right away. */
export function matingMoves(fen: string): string[] {
  const chess = new Chess(fen);
  const out: string[] = [];
  for (const m of chess.moves({ verbose: true })) {
    chess.move(m);
    if (chess.isCheckmate()) out.push(m.from + m.to + (m.promotion ?? ''));
    chess.undo();
  }
  return out;
}

export interface MaterialCheck {
  best: string | null;
  bestScore: number;
  secondScore: number;
  baseline: number;
  unique: boolean;
  fork: boolean;
}

/** Is there exactly one move that wins material (by search at PUZZLE_DEPTH)? */
export function checkMaterialPuzzle(fen: string): MaterialCheck {
  const scored = scoreMoves({ fen }, PUZZLE_DEPTH);
  const turn = fen.split(' ')[1] === 'b' ? -1 : 1;
  const baseline = Math.round(materialBalance(fen) * 100) * turn;
  const best = scored[0];
  const second = scored[1];
  const bestScore = best?.score ?? -Infinity;
  const secondScore = second?.score ?? -Infinity;
  const unique =
    !!best &&
    Math.abs(bestScore) < MATE - 1000 &&
    bestScore >= baseline + WIN_MARGIN &&
    secondScore <= bestScore - UNIQUE_MARGIN &&
    secondScore <= baseline + 100;
  const fork = !!best && (explainMove(fen, best.uci)?.reasons.some((r) => r.includes('vidlička')) ?? false);
  return { best: best?.uci ?? null, bestScore, secondScore, baseline, unique, fork };
}

/** Is `uci` the answer to the puzzle? (Mates count even when another mate exists — the data has none.) */
export function isSolution(puzzle: Puzzle, uci: string): boolean {
  if (puzzle.kind === 'mate1') return matingMoves(puzzle.fen).includes(uci);
  return puzzle.solution[0] === uci;
}
